using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using AntColony.Units;using AntColony.Buildings;using AntColony.Core;using AntColony.UI;
public static class Final1113RestMedia {
 public static async Task<string> Bed(){var b=UnityEngine.Object.FindObjectsByType<Infirmary>(FindObjectsInactive.Exclude).First(x=>x.Patients.Count==2);var cam=Camera.main;UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>().enabled=false;cam.orthographicSize=2.6f;var focus=b.Position;cam.transform.position=focus+new Vector3(-4,5,-5);cam.transform.LookAt(focus);var folder="work/final-motion-1113/media/treatment-bed";Directory.CreateDirectory(folder);SimulationPause.UserSpeed(1);Time.timeScale=.5f;try{for(int i=0;i<48;i++){await Task.Delay(100);if(b.Patients.Count!=2)throw new Exception("patient left before capture");ScreenCapture.CaptureScreenshot(folder+"/"+i.ToString("D3")+".png");}}finally{SimulationPause.UserSpeed(0);}return "48 actual treatment/sleep Game frames, .5x simulation, no Preview";}
 public static async Task<string> Eyes(){SimulationPause.UserSpeed(0);var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.IsColonyMember);c.TreatmentFacility?.Release(c);c.CommandStop();c.SetJobEnabled(CommanderJobs.All,false);var duty=c.WorkState.duty;var hold=c.WorkState.holdDeployment;c.WorkState.duty=CommanderDuty.Deployed;c.WorkState.holdDeployment=true;var p=c.GetComponent<MeshyNativeMotionPlayer>();p.PreviewMotion=null;var origin=c.transform.Find("Kemono");var appearance=origin.GetComponent<KemonoAppearance>();appearance.SetVariant("Hair","BOB");var position=c.Position+Vector3.left*5;if(UnityEngine.AI.NavMesh.SamplePosition(position,out var hit,3,UnityEngine.AI.NavMesh.AllAreas))c.Agent.Warp(hit.position);SimulationPause.UserSpeed(1);await Task.Delay(200);var head=p.NativeModel.GetComponentsInChildren<Transform>().First(t=>t.name=="mixamorig:Head");var cam=Camera.main;UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>().enabled=false;cam.orthographicSize=.55f;cam.nearClipPlane=.02f;var focus=head.position+Vector3.up*.07f;cam.transform.position=focus+origin.forward*3+Vector3.up*.04f;cam.transform.LookAt(focus);var folder="work/final-motion-1113/media/blinking";Directory.CreateDirectory(folder);float max=0;try{for(int i=0;i<90;i++){await Task.Delay(70);var f=p.NativeModel.GetComponentsInChildren<SkinnedMeshRenderer>().First(s=>s.name.StartsWith("Part_Face_"));max=Mathf.Max(max,f.GetBlendShapeWeight(f.sharedMesh.GetBlendShapeIndex("Blink")));ScreenCapture.CaptureScreenshot(folder+"/"+i.ToString("D3")+".png");}}finally{SimulationPause.UserSpeed(0);c.WorkState.duty=duty;c.WorkState.holdDeployment=hold;}var report="90 actual Game frames, automatic blink, no Preview; sampled maxBlink="+max;File.WriteAllText(folder+"/capture.txt",report);return report;}
}
